create policy "own profile" on public.profiles for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "member reads org" on public.organizations for select using (public.is_member(id));
create policy "member reads memberships" on public.organization_members for select using (user_id = auth.uid() or public.is_member(organization_id));
create policy "member reads subscription" on public.subscriptions for select using (public.is_member(organization_id));

-- Research data: read-only for signed-in users; writes via service role only.
create policy "read research" on public.products for select to authenticated using (true);
create policy "read research" on public.product_metrics for select to authenticated using (true);
create policy "read research" on public.product_observations for select to authenticated using (true);
create policy "read research" on public.advertisements for select to authenticated using (true);
create policy "read research" on public.ad_observations for select to authenticated using (true);
create policy "read research" on public.stores for select to authenticated using (true);
create policy "read research" on public.store_products for select to authenticated using (true);
create policy "read research" on public.store_snapshots for select to authenticated using (true);
create policy "read research" on public.trend_signals for select to authenticated using (true);
create policy "read runs" on public.connector_runs for select to authenticated using (true);
create policy "read runs" on public.alert_runs for select to authenticated using (true);

-- User-owned data
create policy "own collections" on public.collections for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own collection items" on public.collection_items for all
  using (exists (select 1 from public.collections c where c.id = collection_id and c.user_id = auth.uid()))
  with check (exists (select 1 from public.collections c where c.id = collection_id and c.user_id = auth.uid()));
create policy "own watchlist" on public.watchlists for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own alerts" on public.alerts for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own notifications" on public.notifications for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own reports" on public.reports for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own usage read" on public.usage_events for select using (user_id = auth.uid());
create policy "own usage insert" on public.usage_events for insert with check (user_id = auth.uid());
-- Integrations: users can see status rows, but tokens are only ever read server-side with the service role.
create policy "own integrations read" on public.connected_integrations for select using (user_id = auth.uid());
create policy "own store data" on public.own_store_products for select
  using (exists (select 1 from public.connected_integrations i where i.id = integration_id and i.user_id = auth.uid()));
create policy "own store sales" on public.own_store_daily_sales for select
  using (exists (select 1 from public.connected_integrations i where i.id = integration_id and i.user_id = auth.uid()));
revoke all on public.connected_integrations from authenticated, anon;
grant select (id, user_id, organization_id, provider, external_account, scopes, status, last_sync_at, last_error, created_at, updated_at)
  on public.connected_integrations to authenticated;

-- ═══ 0002_monitoring.sql ═══
-- TrendHunter monitoring: per-user alert runs, rule scheduling, private operations logs, scan log and data
-- retention. Applies after 0001_init.sql. Background jobs use the service role (bypasses RLS); end users only
-- ever read their own alert runs.

-- ---------------------------------------------------------------------------
-- Alert runs belong to one user
-- ---------------------------------------------------------------------------
-- Rows written before this migration were system-wide (no owner, possibly evaluated against demo data):
-- they cannot be attributed to anyone and must not be shown, so they are dropped.
delete from public.alert_runs;

alter table public.alert_runs
  add column user_id uuid not null references auth.users (id) on delete cascade,
  add column data_as_of date,
  add column emails_sent int not null default 0;
create index alert_runs_user_idx on public.alert_runs (user_id, started_at desc);
create index alert_runs_started_idx on public.alert_runs (started_at);

comment on column public.alert_runs.message is
  'Machine-readable reason code (no_live_data, data_unavailable, rule_limit, email_failed, evaluation_failed; see lib/monitoring.ts RUN_REASONS). Never raw provider or database error text: users read this row.';
comment on column public.alert_runs.data_as_of is 'Latest day covered by the live research data the rules were evaluated against (null when not evaluated).';

drop policy "read runs" on public.alert_runs;
create policy "own runs read" on public.alert_runs for select to authenticated using (user_id = auth.uid());
-- Writes (scheduled scan, manual checks after the session check) go through the service role only.
revoke insert, update, delete on public.alert_runs from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Rule scheduling: a rule is due when its last scheduled turn started before the current UTC period of its
-- frequency (hour, day, ISO week; lib/monitoring.ts → isRuleDue). Set by scheduled runs only; manual checks
-- do not move it.
-- ---------------------------------------------------------------------------
alter table public.alerts add column last_scheduled_at timestamptz;
comment on column public.alerts.last_scheduled_at is
  'Start of the last scheduled scan that gave this rule its turn (evaluated, skipped without live data, or over the plan limit).';

-- ---------------------------------------------------------------------------
-- Connector runs are platform operations logs: no end-user access at all.
-- Server routes read them with the service role and return sanitized error categories.
-- ---------------------------------------------------------------------------
drop policy "read runs" on public.connector_runs;
revoke all on public.connector_runs from anon, authenticated;
create index connector_runs_started_idx on public.connector_runs (started_at);
create index connector_runs_success_idx on public.connector_runs (connector, started_at desc) where status = 'success';

-- ---------------------------------------------------------------------------
-- One row per scheduled scan: connector decisions, ingestion, evaluation summary and retention counts
-- (retention is null when the daily purge was not due).
-- ---------------------------------------------------------------------------
create table public.scan_runs (
  id bigint generated always as identity primary key,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  status text not null check (status in ('running', 'success', 'failed')),
  connectors jsonb not null default '{}',
  records int not null default 0,
  evaluation jsonb not null default '{}',
  retention jsonb,
  error text
);
create index scan_runs_started_idx on public.scan_runs (started_at desc);
create index scan_runs_purged_idx on public.scan_runs (started_at desc) where retention ->> 'status' = 'success';
alter table public.scan_runs enable row level security;
revoke all on public.scan_runs from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Retention
-- ---------------------------------------------------------------------------
create index usage_events_created_idx on public.usage_events (created_at);
create index notifications_read_created_idx on public.notifications (created_at) where read;
create index ad_observations_connector_date_idx on public.ad_observations (connector, date);
create index product_observations_connector_date_idx on public.product_observations (source_connector, date);

-- Deletes rows past their retention window and returns the number of deleted rows per table.
-- `cutoffs` (built by lib/monitoring.ts → retentionCutoffs; rows dated strictly before a cutoff are deleted):
--   connectors                { "<connector id>": "YYYY-MM-DD" }  raw research rows per connector
--   store_listings_before     date: public storefront listings not seen since (store_products has no connector column)
--   own_store_sales_before    date: merchants' own Shopify daily sales
--   usage_events_before       timestamptz: usage events
--   run_logs_before           timestamptz: connector_runs, alert_runs, scan_runs
--   read_notifications_before timestamptz: notifications already read
-- Safety net: a missing cutoff, or one less than 30 days in the past, skips that category. Demo-seeded rows
-- (is_demo, connector 'demo') are never purged here, and derived aggregates (source_connector 'aggregate') are
-- kept as history.
create or replace function public.purge_expired_data(cutoffs jsonb)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  min_day constant date := current_date - 30;
  min_ts constant timestamptz := now() - interval '30 days';
  c record;
  cutoff date;
  cutoff_ts timestamptz;
  n bigint;
  ads bigint := 0;
  ad_obs bigint := 0;
  product_obs bigint := 0;
  snapshots bigint := 0;
  signals bigint := 0;
  research_products bigint := 0;
  listings bigint := 0;
  own_sales bigint := 0;
  usage bigint := 0;
  connector_logs bigint := 0;
  alert_logs bigint := 0;
  scan_logs bigint := 0;
  read_notifications bigint := 0;
begin
  for c in select key as connector, value from jsonb_each(coalesce(cutoffs -> 'connectors', '{}'::jsonb)) loop
    cutoff := (c.value #>> '{}')::date;
    continue when cutoff is null or cutoff > min_day or c.connector in ('demo', 'aggregate');
    delete from public.ad_observations where connector = c.connector and date < cutoff;
    get diagnostics n = row_count; ad_obs := ad_obs + n;
    delete from public.advertisements where connector = c.connector and last_seen < cutoff and not is_demo;
    get diagnostics n = row_count; ads := ads + n;
    delete from public.product_observations where source_connector = c.connector and date < cutoff;
    get diagnostics n = row_count; product_obs := product_obs + n;
    delete from public.store_snapshots where connector = c.connector and date < cutoff;
    get diagnostics n = row_count; snapshots := snapshots + n;
    delete from public.trend_signals where connector = c.connector and date < cutoff;
    get diagnostics n = row_count; signals := signals + n;
    delete from public.products where source_connector = c.connector and last_detected < cutoff and not is_demo;
    get diagnostics n = row_count; research_products := research_products + n;
  end loop;

  cutoff := (cutoffs ->> 'store_listings_before')::date;
  if cutoff <= min_day then
    delete from public.store_products sp using public.stores s
      where s.id = sp.store_id and not s.is_demo and sp.last_seen < cutoff;
    get diagnostics listings = row_count;
  end if;

  cutoff := (cutoffs ->> 'own_store_sales_before')::date;
  if cutoff <= min_day then
    delete from public.own_store_daily_sales where date < cutoff;
    get diagnostics own_sales = row_count;
  end if;

  cutoff_ts := (cutoffs ->> 'usage_events_before')::timestamptz;
  if cutoff_ts <= min_ts then
    delete from public.usage_events where created_at < cutoff_ts;
    get diagnostics usage = row_count;
  end if;

  cutoff_ts := (cutoffs ->> 'run_logs_before')::timestamptz;
  if cutoff_ts <= min_ts then
    delete from public.connector_runs where started_at < cutoff_ts;
    get diagnostics connector_logs = row_count;
    delete from public.alert_runs where started_at < cutoff_ts;
    get diagnostics alert_logs = row_count;
    delete from public.scan_runs where started_at < cutoff_ts;
    get diagnostics scan_logs = row_count;
  end if;

  cutoff_ts := (cutoffs ->> 'read_notifications_before')::timestamptz;
  if cutoff_ts <= min_ts then
    delete from public.notifications where read and created_at < cutoff_ts;
    get diagnostics read_notifications = row_count;
  end if;

  return jsonb_build_object(
    'advertisements', ads,
    'ad_observations', ad_obs,
    'product_observations', product_obs,
    'store_snapshots', snapshots,
    'trend_signals', signals,
    'products', research_products,
    'store_products', listings,
    'own_store_daily_sales', own_sales,
    'usage_events', usage,
    'connector_runs', connector_logs,
    'alert_runs', alert_logs,
    'scan_runs', scan_logs,
    'notifications', read_notifications
  );
end;
$$;

-- Only background jobs may purge: no execute for end users (Supabase grants functions to anon/authenticated by default).
revoke all on function public.purge_expired_data(jsonb) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.purge_expired_data(jsonb) to service_role;
  end if;
end;
$$;

-- ═══ 0003_plan_limits.sql ═══
-- Plan limits enforced in the database, billing interval, search metering keys,
-- support requests, and no direct client access to research tables.
--
-- The application checks every limit before writing (src/lib/server/workspace-db.ts).
-- These triggers are defence in depth: RLS lets signed-in users write their own
-- rows through PostgREST with the public anon key, so limits must also hold there.

-- ---------------------------------------------------------------------------
-- Plan limits (must match src/lib/plans.ts; tests/plan-limits.test.ts checks it)
-- ---------------------------------------------------------------------------
create table public.plan_limits (
  plan text primary key check (plan in ('free', 'pro', 'business')),
  collections integer not null,
  saved_items integer not null,
  alert_rules integer not null,
  watchlists boolean not null,
  alerts boolean not null
);
insert into public.plan_limits (plan, collections, saved_items, alert_rules, watchlists, alerts) values
  ('free', 2, 20, 0, false, false),
  ('pro', 50, 1000, 25, true, true),
  ('business', 500, 10000, 200, true, true);
alter table public.plan_limits enable row level security;
create policy "read plan limits" on public.plan_limits for select to authenticated using (true);

-- Plan of an organization: its active (or trialing) subscription, else Free.
create or replace function public.org_plan(org uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce(
    (select s.plan from public.subscriptions s
      where s.organization_id = org and s.status in ('active', 'trialing')
      order by case s.plan when 'business' then 3 when 'pro' then 2 else 1 end desc
      limit 1),
    'free')
$$;

-- Limits that apply to a user-owned row: the row's organization, else the user's first one.
create or replace function public.limits_for(uid uuid, org uuid)
returns public.plan_limits language sql stable security definer set search_path = public as $$
  select l.* from public.plan_limits l
  where l.plan = public.org_plan(coalesce(org,
    (select m.organization_id from public.organization_members m where m.user_id = uid order by m.created_at limit 1)))
$$;

create or replace function public.enforce_plan_limits()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  lim public.plan_limits;
  owner uuid;
  org uuid;
  n integer;
begin
  if tg_table_name = 'collection_items' then
    select c.user_id, c.organization_id into owner, org from public.collections c where c.id = new.collection_id;
  else
    owner := new.user_id;
    org := new.organization_id;
  end if;
  if owner is null then
    return new;
  end if;
  -- The swipe file is created automatically and never counts toward the collection limit.
  if tg_table_name = 'collections' then
    if new.kind = 'swipe' then
      return new;
    end if;
  end if;
  -- Serialize concurrent writes of the same user so two inserts cannot both pass a count.
  perform pg_advisory_xact_lock(hashtext('plan_limits:' || owner::text));
  lim := public.limits_for(owner, org);

  if tg_table_name = 'collections' then
    select count(*) into n from public.collections where user_id = owner and kind = 'standard' and organization_id is not distinct from org;
    if n >= lim.collections then
      raise exception 'limit_collections' using errcode = 'check_violation';
    end if;
  elsif tg_table_name = 'collection_items' then
    select count(*) into n from public.collection_items i join public.collections c on c.id = i.collection_id where c.user_id = owner and c.organization_id is not distinct from org;
    if n >= lim.saved_items then
      raise exception 'limit_items' using errcode = 'check_violation';
    end if;
  elsif tg_table_name = 'watchlists' then
    if not lim.watchlists then
      raise exception 'plan_required' using errcode = 'check_violation';
    end if;
    select count(*) into n from public.watchlists where user_id = owner and organization_id is not distinct from org;
    if n >= lim.saved_items then
      raise exception 'limit_items' using errcode = 'check_violation';
    end if;
  elsif tg_table_name = 'alerts' then
    if tg_op = 'UPDATE' then
      -- Re-activating a rule requires a plan that includes alerts.
      if new.active and not old.active and not lim.alerts then
        raise exception 'plan_required' using errcode = 'check_violation';
      end if;
      return new;
    end if;
    if not lim.alerts then
      raise exception 'plan_required' using errcode = 'check_violation';
    end if;
    select count(*) into n from public.alerts where user_id = owner and organization_id is not distinct from org;
    if n >= lim.alert_rules then
      raise exception 'limit_rules' using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;

create trigger collections_plan_limits before insert on public.collections
  for each row execute function public.enforce_plan_limits();
create trigger collection_items_plan_limits before insert on public.collection_items
  for each row execute function public.enforce_plan_limits();
create trigger watchlists_plan_limits before insert on public.watchlists
  for each row execute function public.enforce_plan_limits();
create trigger alerts_plan_limits before insert or update of active on public.alerts
  for each row execute function public.enforce_plan_limits();

-- ---------------------------------------------------------------------------
-- Search metering: one usage event per distinct query and day (page turns are free)
-- ---------------------------------------------------------------------------
alter table public.usage_events add column query_key text;
create index usage_events_query_idx on public.usage_events (user_id, feature, query_key, created_at desc);

-- ---------------------------------------------------------------------------
-- Billing interval and cancellation state (written by the Stripe webhook only)
-- ---------------------------------------------------------------------------
alter table public.subscriptions
  add column billing_interval text check (billing_interval in ('month', 'year')),
  add column cancel_at_period_end boolean not null default false;

-- ---------------------------------------------------------------------------
-- Support requests. Written by the server after a session check; priority is
-- derived from the plan on the server, never from the client.
-- ---------------------------------------------------------------------------
create table public.support_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  organization_id uuid references public.organizations (id) on delete set null,
  plan text not null check (plan in ('free', 'pro', 'business')),
  priority boolean not null default false,
  category text not null check (category in ('question', 'bug', 'billing', 'data', 'other')),
  subject text not null check (char_length(subject) between 1 and 160),
  message text not null check (char_length(message) between 1 and 5000),
  status text not null default 'open' check (status in ('open', 'answered', 'closed')),
  emailed_at timestamptz,
  created_at timestamptz not null default now()
);
create index support_requests_user_idx on public.support_requests (user_id, created_at desc);
alter table public.support_requests enable row level security;
create policy "own support requests" on public.support_requests for select using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Research data is served only by server routes (service role) that apply plan
-- metering, filters and export gating. No direct client reads.
-- ---------------------------------------------------------------------------
drop policy if exists "read research" on public.products;
drop policy if exists "read research" on public.product_metrics;
drop policy if exists "read research" on public.product_observations;
drop policy if exists "read research" on public.advertisements;
drop policy if exists "read research" on public.ad_observations;
drop policy if exists "read research" on public.stores;
drop policy if exists "read research" on public.store_products;
drop policy if exists "read research" on public.store_snapshots;
drop policy if exists "read research" on public.trend_signals;

-- ═══ 0004_team_workspaces.sql ═══
-- Business workspaces, team collaboration and role-based access.
--
-- Organization = workspace. A user can belong to several organizations; the
-- active one is chosen server-side (httpOnly cookie, always re-validated
-- against organization_members). Workspaces created by a Business owner are
-- billed under that owner's organization (billing_organization_id), so the
-- plan of a workspace is the active subscription of
-- coalesce(billing_organization_id, id).
--
-- Membership, invitation and workspace writes happen only in server routes
-- with the service role, after role and plan checks: authenticated users get
-- no write policy on organizations, organization_members or invitations.

-- ---------------------------------------------------------------------------
-- Organizations: billing parent
-- ---------------------------------------------------------------------------
alter table public.organizations
  add column billing_organization_id uuid references public.organizations (id) on delete set null,
  add constraint organizations_billing_not_self check (billing_organization_id is null or billing_organization_id <> id);
create index organizations_billing_idx on public.organizations (billing_organization_id);

-- One level only: a billing organization pays for itself and is never billed elsewhere.
create or replace function public.check_billing_organization()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.billing_organization_id is not null and (
    exists (select 1 from public.organizations p where p.id = new.billing_organization_id and p.billing_organization_id is not null)
    or exists (select 1 from public.organizations c where c.billing_organization_id = new.id)
  ) then
    raise exception 'billing_organization_nested' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
create trigger organizations_billing_check before insert or update of billing_organization_id on public.organizations
  for each row execute function public.check_billing_organization();

-- ---------------------------------------------------------------------------
-- Helpers (security definer: they read memberships regardless of RLS)
-- ---------------------------------------------------------------------------
create or replace function public.has_org_role(org uuid, roles text[])
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.organization_members m where m.organization_id = org and m.user_id = auth.uid() and m.role = any (roles));
$$;

-- True when the caller and `other` share at least one organization.
create or replace function public.is_teammate(other uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.organization_members mine
    join public.organization_members theirs on theirs.organization_id = mine.organization_id
    where mine.user_id = auth.uid() and theirs.user_id = other
  );
$$;

-- A user's default workspace: oldest owned membership, else oldest membership.
create or replace function public.default_organization_for(uid uuid)
returns uuid language sql stable security definer set search_path = public as $$
  select m.organization_id from public.organization_members m
  where m.user_id = uid
  order by (m.role = 'owner') desc, m.created_at, m.organization_id
  limit 1;
$$;
revoke execute on function public.default_organization_for(uuid) from public, anon, authenticated;

-- Plan of a workspace: the best active (or trialing) subscription of the
-- organization that pays for it, coalesce(billing_organization_id, id); else Free.
-- Same signature as public.org_plan in 0003_plan_limits.sql (when present), so
-- anything resolving a plan through it follows the billing organization.
create or replace function public.org_plan(org uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce(
    (select s.plan from public.subscriptions s
      where s.organization_id = coalesce((select o.billing_organization_id from public.organizations o where o.id = org), org)
        and s.status in ('active', 'trialing')
      order by case s.plan when 'business' then 3 when 'pro' then 2 else 1 end desc
      limit 1),
    'free')
$$;

-- The caller's workspaces with their role, effective plan and member count.
create or replace function public.my_workspaces()
returns table (organization_id uuid, name text, role text, plan text, billing_organization_id uuid, member_count int, created_at timestamptz, joined_at timestamptz)
language sql stable security definer set search_path = public as $$
  select
    o.id,
    o.name,
    m.role,
    public.org_plan(o.id),
    coalesce(o.billing_organization_id, o.id),
    (select count(*)::int from public.organization_members x where x.organization_id = o.id),
    o.created_at,
    m.created_at
  from public.organization_members m
  join public.organizations o on o.id = m.organization_id
  where m.user_id = auth.uid()
  order by m.created_at, o.id;
$$;
revoke execute on function public.my_workspaces() from public, anon;
grant execute on function public.my_workspaces() to authenticated;

-- Member directory (names and emails) for team management and seat counting.
-- Service role only: routes call it after checking the caller's membership.
create or replace function public.org_member_directory(orgs uuid[])
returns table (organization_id uuid, user_id uuid, role text, name text, email text, joined_at timestamptz)
language sql stable security definer set search_path = public, auth as $$
  select m.organization_id, m.user_id, m.role, p.name, u.email, m.created_at
  from public.organization_members m
  join auth.users u on u.id = m.user_id
  left join public.profiles p on p.user_id = m.user_id
  where m.organization_id = any (orgs)
  order by m.created_at, m.user_id;
$$;
revoke execute on function public.org_member_directory(uuid[]) from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.org_member_directory(uuid[]) to service_role;
    grant execute on function public.default_organization_for(uuid) to service_role;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Invitations (only a SHA-256 hash of the token is stored)
-- ---------------------------------------------------------------------------
create table public.organization_invitations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  email text not null check (email = lower(btrim(email)) and char_length(email) between 3 and 254 and position('@' in email) > 1),
  role text not null default 'member' check (role in ('admin', 'member')),
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  invited_by uuid references auth.users (id) on delete set null,
  expires_at timestamptz not null default (now() + interval '7 days'),
  accepted_at timestamptz,
  accepted_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
-- One open invitation per address and workspace (re-inviting replaces it).
create unique index organization_invitations_pending_idx on public.organization_invitations (organization_id, email) where accepted_at is null;

alter table public.organization_invitations enable row level security;
create policy "admins read invitations" on public.organization_invitations for select
  using (public.has_org_role(organization_id, array['owner', 'admin']));
-- Token hashes never leave the server; writes go through service-role routes.
revoke all on public.organization_invitations from anon, authenticated;
grant select (id, organization_id, email, role, invited_by, expires_at, accepted_at, accepted_by, created_at)
  on public.organization_invitations to authenticated;

-- Teammates can see each other's display name.
create policy "teammates read profiles" on public.profiles for select using (public.is_teammate(user_id));

-- ---------------------------------------------------------------------------
-- Workspace scoping of user data
-- ---------------------------------------------------------------------------
alter table public.notifications add column if not exists organization_id uuid references public.organizations (id) on delete cascade;
alter table public.collections add column if not exists visibility text not null default 'private' check (visibility in ('private', 'team'));

-- Backfill rows written before workspaces existed with each user's first organization.
update public.collections set organization_id = public.default_organization_for(user_id) where organization_id is null;
update public.watchlists set organization_id = public.default_organization_for(user_id) where organization_id is null;
update public.alerts set organization_id = public.default_organization_for(user_id) where organization_id is null;
update public.notifications n
  set organization_id = coalesce((select a.organization_id from public.alerts a where a.id = n.alert_id), public.default_organization_for(n.user_id))
  where organization_id is null;

-- Inserts that omit the workspace (older code paths, background jobs) land in the user's default one.
create or replace function public.set_default_organization()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.organization_id is null then
    new.organization_id := public.default_organization_for(new.user_id);
  end if;
  return new;
end;
$$;

-- Notifications follow the workspace of the alert that produced them.
create or replace function public.set_notification_organization()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.organization_id is null and new.alert_id is not null then
    select a.organization_id into new.organization_id from public.alerts a where a.id = new.alert_id;
  end if;
  if new.organization_id is null then
    new.organization_id := public.default_organization_for(new.user_id);
  end if;
  return new;
end;
$$;

create trigger collections_default_org before insert on public.collections for each row execute function public.set_default_organization();
create trigger watchlists_default_org before insert on public.watchlists for each row execute function public.set_default_organization();
create trigger alerts_default_org before insert on public.alerts for each row execute function public.set_default_organization();
create trigger notifications_default_org before insert on public.notifications for each row execute function public.set_notification_organization();

-- The same item can be watched in several workspaces.
alter table public.watchlists drop constraint if exists watchlists_user_id_item_type_ref_id_key;
alter table public.watchlists add constraint watchlists_user_org_item_key unique nulls not distinct (user_id, organization_id, item_type, ref_id);

-- One swipe file per user and workspace (created lazily by the server). Extra
-- swipe collections from before this migration become standard collections.
update public.collections c set kind = 'standard'
where c.kind = 'swipe' and exists (
  select 1 from public.collections d
  where d.kind = 'swipe' and d.user_id = c.user_id and d.organization_id is not distinct from c.organization_id
    and (d.created_at, d.id) < (c.created_at, c.id)
);
create unique index collections_swipe_unique_idx on public.collections (user_id, organization_id) where kind = 'swipe';

create index collections_org_idx on public.collections (organization_id, visibility);
create index watchlists_org_user_idx on public.watchlists (organization_id, user_id);
create index alerts_org_user_idx on public.alerts (organization_id, user_id);
create index notifications_user_org_idx on public.notifications (user_id, organization_id, created_at desc);

-- ---------------------------------------------------------------------------
-- RLS: creators edit their rows only inside workspaces they belong to;
-- members read "team" collections (and their items) of their workspaces.
-- ---------------------------------------------------------------------------
drop policy if exists "own collections" on public.collections;
create policy "own collections" on public.collections for all
  using (user_id = auth.uid())
  with check (user_id = auth.uid() and public.is_member(organization_id));
create policy "members read team collections" on public.collections for select
  using (visibility = 'team' and public.is_member(organization_id));

drop policy if exists "own collection items" on public.collection_items;
create policy "own collection items" on public.collection_items for all
  using (exists (select 1 from public.collections c where c.id = collection_id and c.user_id = auth.uid()))
  with check (exists (select 1 from public.collections c where c.id = collection_id and c.user_id = auth.uid() and public.is_member(c.organization_id)));
create policy "members read team collection items" on public.collection_items for select
  using (exists (select 1 from public.collections c where c.id = collection_id and c.visibility = 'team' and public.is_member(c.organization_id)));

drop policy if exists "own watchlist" on public.watchlists;
create policy "own watchlist" on public.watchlists for all
  using (user_id = auth.uid())
  with check (user_id = auth.uid() and public.is_member(organization_id));

drop policy if exists "own alerts" on public.alerts;
create policy "own alerts" on public.alerts for all
  using (user_id = auth.uid())
  with check (user_id = auth.uid() and public.is_member(organization_id));

-- ═══ 0005_provenance.sql ═══
-- TrendHunter 0005: truthful connector mappings and listing provenance.
-- Applies after 0001_init.sql (independent of 0002-0004).
--
-- * Values a provider does not disclose are stored as unknown (null / 'unknown'), never as a guess.
-- * Values inferred by TrendHunter carry an explicit basis column, so they are shown as estimates.
-- * Store listings record which connector observed them and when.
-- * Connector runs can end 'partial' (some records stored, some failed or the run was cut short).

-- ---------------------------------------------------------------------------
-- Advertisements
-- ---------------------------------------------------------------------------
alter table public.advertisements
  alter column language drop not null,
  alter column category drop not null,
  alter column cta set default 'unknown',
  add column product_match_basis text check (product_match_basis in ('source', 'search_term', 'token_overlap')),
  add column category_basis text check (category_basis in ('source', 'product', 'keyword_classifier')),
  add column placements text[] not null default '{}';

comment on column public.advertisements.language is 'ISO 639-1 code as reported by the source; null when the source does not report it.';
comment on column public.advertisements.format is 'video | image | carousel as reported by the source; ''unknown'' when not disclosed (e.g. Meta Ad Library API).';
comment on column public.advertisements.cta is 'Call to action as reported by the source; ''unknown'' when not disclosed.';
comment on column public.advertisements.category is 'Null when neither the source nor an estimate (see category_basis) provides one.';
comment on column public.advertisements.product_match_basis is
  'How product_id was assigned. source = given by the data provider; search_term = the tracked product whose name was the provider search term (estimate); token_overlap = deterministic token overlap between ad text and product names/tags (estimate, lib/connectors/matching.ts).';
comment on column public.advertisements.category_basis is
  'How category was assigned. source = given by the data provider; product = category of the linked product (estimate); keyword_classifier = deterministic multilingual keyword classifier (estimate).';
comment on column public.advertisements.placements is 'Placements reported by the source (Meta publisher_platforms), lower case.';
comment on column public.advertisements.snapshot_url is 'HTTPS page of the ad in the platform''s public ad library (tokenless). Linked, never embedded.';

-- Rows stored before this migration by the official-API connectors carried fixed placeholder values.
-- Meta: format 'image', cta 'learn_more', category 'home', and ad_snapshot_url (which embeds the API access token).
update public.advertisements
set format = 'unknown',
    cta = 'unknown',
    category = null,
    category_basis = null,
    snapshot_url = 'https://www.facebook.com/ads/library/?id=' || external_id
where connector = 'meta_ad_library' and not is_demo;
-- TikTok: format 'video', cta 'learn_more', category 'home', language 'en' (the query endpoint returns none of them).
update public.advertisements
set format = 'unknown',
    cta = 'unknown',
    category = null,
    category_basis = null,
    language = null,
    snapshot_url = 'https://library.tiktok.com/ads/detail/?ad_id=' || external_id
where connector = 'tiktok_commercial_content' and not is_demo;
-- Product links that existed before (demo generator, licensed feed) were supplied by the source.
update public.advertisements set product_match_basis = 'source' where product_id is not null and product_match_basis is null;
update public.advertisements set category_basis = 'source' where category is not null and category_basis is null;

alter table public.advertisements
  add constraint advertisements_snapshot_url_https check (snapshot_url is null or snapshot_url ~ '^https://');

-- Observations were written active=true for every fetched ad, including stopped ones.
-- Meta reports the delivery stop date (last_seen): later observation days were not active.
update public.ad_observations o
set active = false
from public.advertisements a
where a.id = o.ad_id and o.active and not a.is_demo and a.connector = 'meta_ad_library' and o.date > a.last_seen;
-- TikTok / licensed feeds report the last shown date, refreshed with about a day of delay.
update public.ad_observations o
set active = false
from public.advertisements a
where a.id = o.ad_id and o.active and not a.is_demo and a.connector in ('tiktok_commercial_content', 'licensed_dataset') and o.date > a.last_seen + 1;

-- ---------------------------------------------------------------------------
-- Stores and listings
-- ---------------------------------------------------------------------------
alter table public.stores alter column currency drop not null;
comment on column public.stores.currency is 'ISO 4217 code read from a public storefront endpoint (Shopify /meta.json or /cart.js, WooCommerce Store API); null when not exposed.';
comment on column public.stores.technology is '{"platform": shopify|woocommerce|unknown, "verified": bool}; verified only when the platform''s public endpoint returned a valid response.';

alter table public.store_products
  alter column currency drop not null,
  add column source_connector text,
  add column source_kind text check (source_kind in ('measured', 'estimate', 'ai', 'demo')),
  add column observed_at timestamptz;

comment on column public.store_products.currency is 'Currency of the displayed price as exposed by the storefront; null when unknown or ambiguous.';
comment on column public.store_products.source_connector is 'Connector that observed the listing (public_storefronts, demo).';
comment on column public.store_products.observed_at is 'When the listing was last observed.';

-- Listings written before this migration came from the demo seed or the storefront crawler,
-- which hard-coded the currency to EUR (products.json does not state it).
update public.store_products sp
set source_connector = case when s.is_demo then 'demo' else 'public_storefronts' end,
    source_kind = case when s.is_demo then 'demo' else 'measured' end,
    observed_at = sp.last_seen::timestamptz,
    currency = case when s.is_demo then sp.currency end
from public.stores s
where s.id = sp.store_id and sp.source_connector is null;

-- ---------------------------------------------------------------------------
-- Connector runs
-- ---------------------------------------------------------------------------
alter table public.connector_runs drop constraint if exists connector_runs_status_check;
alter table public.connector_runs
  add constraint connector_runs_status_check check (status in ('running', 'success', 'partial', 'failed', 'skipped'));
comment on column public.connector_runs.status is 'partial = some records stored while others failed, or the run stopped at its time/request budget or a rate limit.';

-- ═══ 0006_shopify.sql ═══
-- Shopify integration: revocation, scheduled daily sync, store currency,
-- daily inventory history and manual market matches.
--
-- All writes go through the server (service role, src/lib/server/shopify.ts).
-- Clients can only read rows of their own integrations.

-- ---------------------------------------------------------------------------
-- Connections
-- ---------------------------------------------------------------------------
-- A revoked integration (app uninstalled, 401/403 from Shopify) keeps its row so
-- the owner sees the status and can reconnect, but its token is deleted.
alter table public.connected_integrations alter column access_token_encrypted drop not null;
alter table public.connected_integrations
  add constraint connected_integrations_revoked_without_token
    check (status <> 'revoked' or access_token_encrypted is null),
  add constraint connected_integrations_active_with_token
    check (status = 'revoked' or access_token_encrypted is not null);

-- Automatic sync schedule: due when the last sync (or attempt) is older than the interval.
alter table public.connected_integrations
  add column sync_interval_hours integer not null default 24 check (sync_interval_hours between 1 and 168),
  add column last_attempt_at timestamptz;

create index connected_integrations_shop_idx on public.connected_integrations (provider, external_account);

grant select (sync_interval_hours, last_attempt_at) on public.connected_integrations to authenticated;

-- ---------------------------------------------------------------------------
-- Store currency (prices and revenue are shown in the store's own currency)
-- ---------------------------------------------------------------------------
alter table public.own_store_products
  add column currency text check (currency ~ '^[A-Z]{3}$');

-- ---------------------------------------------------------------------------
-- Daily inventory snapshots (one row per product and day, kept 400 days)
-- ---------------------------------------------------------------------------
create table public.own_store_inventory_snapshots (
  integration_id uuid not null references public.connected_integrations (id) on delete cascade,
  product_external_id text not null,
  date date not null,
  inventory integer not null,
  primary key (integration_id, product_external_id, date)
);

-- ---------------------------------------------------------------------------
-- Manual market matches. No row: automatic name-similarity estimate.
-- market_product_id null: the owner stated there is no comparable product.
-- Removing a tracked product reverts its manual matches to the estimate.
-- ---------------------------------------------------------------------------
create table public.own_store_market_matches (
  integration_id uuid not null references public.connected_integrations (id) on delete cascade,
  product_external_id text not null,
  market_product_id text references public.products (id) on delete cascade,
  updated_at timestamptz not null default now(),
  primary key (integration_id, product_external_id)
);

alter table public.own_store_inventory_snapshots enable row level security;
alter table public.own_store_market_matches enable row level security;

create policy "own store inventory" on public.own_store_inventory_snapshots for select
  using (exists (select 1 from public.connected_integrations i where i.id = integration_id and i.user_id = auth.uid()));
create policy "own store matches" on public.own_store_market_matches for select
  using (exists (select 1 from public.connected_integrations i where i.id = integration_id and i.user_id = auth.uid()));

revoke insert, update, delete, truncate on public.own_store_inventory_snapshots from authenticated, anon;
revoke insert, update, delete, truncate on public.own_store_market_matches from authenticated, anon;

-- ═══ 0007_ad_media.sql ═══
-- TrendHunter 0007: authorized ad media (playable videos / images).
-- Applies after 0005_provenance.sql.
--
-- * Only media URLs a provider officially returns for display are stored (TikTok Commercial Content API
--   ad.videos[].url / cover_image_url and ad.image_urls; a licensed feed's media entries). Nothing is
--   scraped, downloaded or re-hosted; Meta's Ad Library API returns no media URL, so Meta rows keep [].
-- * Every URL is HTTPS and carries no access token (Meta's ad_snapshot_url embeds one and is never stored).
-- * Entry shape: {"type": "video"|"image", "url": "https://…", "posterUrl"?: "https://…",
--   "source": "<connector>", "authorized": true}.

create or replace function public.ad_media_valid(m jsonb)
returns boolean
language sql
immutable
set search_path = pg_catalog
as $$
  select jsonb_typeof(m) = 'array'
    and jsonb_array_length(m) <= 10
    and not exists (
      select 1
      from jsonb_array_elements(m) as e(v)
      where jsonb_typeof(e.v) is distinct from 'object'
         or coalesce(e.v ->> 'type', '') not in ('video', 'image')
         or jsonb_typeof(e.v -> 'url') is distinct from 'string'
         or (e.v ->> 'url') !~ '^https://'
         or (e.v ->> 'url') ~* '[?&]access_token='
         or length(e.v ->> 'url') > 2048
         or (
           e.v ? 'posterUrl' and jsonb_typeof(e.v -> 'posterUrl') <> 'null'
           and (
             jsonb_typeof(e.v -> 'posterUrl') <> 'string'
             or (e.v ->> 'posterUrl') !~ '^https://'
             or (e.v ->> 'posterUrl') ~* '[?&]access_token='
             or length(e.v ->> 'posterUrl') > 2048
           )
         )
         or jsonb_typeof(e.v -> 'source') is distinct from 'string'
         or (e.v -> 'authorized') is distinct from 'true'::jsonb
    )
$$;

comment on function public.ad_media_valid(jsonb) is
  'True when every entry is {type video|image, url https (tokenless), optional posterUrl https, source, authorized true}; at most 10 entries.';

alter table public.advertisements
  add column if not exists media jsonb not null default '[]'::jsonb;

alter table public.advertisements
  drop constraint if exists advertisements_media_valid;
alter table public.advertisements
  add constraint advertisements_media_valid check (public.ad_media_valid(media));

comment on column public.advertisements.media is
  'Authorized creative media returned by the source for display (TikTok Commercial Content API videos/images, licensed feed). HTTPS, tokenless, never re-hosted; provider URLs may expire and are refreshed at each sync. [] when none (always for Meta).';

-- ═══ 0008_active_advertisers.sql ═══
-- TrendHunter 0008: active advertisers — the default quality bar of Ad Spy and every ad list.
-- Applies after 0007_ad_media.sql.
--
-- Same rule as src/lib/advertisers.ts (keep both in sync; supabase/tests/0008_active_advertisers.test.sql
-- and tests/active-advertisers.test.ts check one shared fixture file against both):
--
-- * Advertiser identity = advertiser_key(advertiser): Unicode NFKD, combining accents (U+0300–U+036F)
--   removed, lower case, Greek final sigma folded (ς → σ: JavaScript lowercases a word-final Σ to ς,
--   lower() always to σ), runs of ASCII whitespace collapsed to one space, trimmed.
--   'Maison Éclat', ' maison  eclat ' and 'MAISON ECLAT' are one advertiser; so are 'ΟΔΟΣ' and 'Οδος'.
-- * An ad is active (currently running) on as_of when first_seen <= as_of and
--   - ended (the latest sync reported it stopped: advertisements.ended, below): last_seen >= as_of —
--     an ended ad runs through its last delivery day, so an ad that stopped yesterday is not active;
--   - otherwise: last_seen >= as_of - 1 (libraries refresh with about a day of delay, connectors sync
--     daily: the ad_observations.active rule of the connectors).
--   Also the Ad Spy "active ads only" filter.
-- * An advertiser qualifies on as_of when at least min_ads (default 5) of its active ads were first
--   seen at least min_days (default 7) days before as_of (first_seen <= as_of - min_days).
--   Every ad of a qualifying advertiser is listed; the others are hidden by default.
--
-- Access: advertiser_activity() and ads_of_active_advertisers() are called by the server with the
-- service role only (PostgREST RPC; arguments travel in the JSON body, never in filter strings).
-- Both are SECURITY INVOKER: the service role already reads every research row, so no definer
-- rights are needed. advertiser_key() is a pure function used by a generated column, executable
-- by everyone.

create or replace function public.advertiser_key(name text)
returns text
language sql
immutable
parallel safe
set search_path = pg_catalog
as $$
  select btrim(
    regexp_replace(
      translate(lower(regexp_replace(normalize(coalesce(name, ''), NFKD), '[\u0300-\u036f]', '', 'g')), U&'\03C2', U&'\03C3'),
      '[\t\n\v\f\r ]+', ' ', 'g'
    ),
    ' '
  )
$$;

comment on function public.advertiser_key(text) is
  'Advertiser identity: NFKD, accents removed, lower case, final sigma folded to σ, whitespace collapsed, trimmed. Mirrors advertiserKey() in src/lib/advertisers.ts.';

-- Stored so the identity is indexed and filterable (Ad Spy advertiser search uses it too).
alter table public.advertisements
  add column if not exists advertiser_key text generated always as (public.advertiser_key(advertiser)) stored;

comment on column public.advertisements.advertiser_key is
  'Normalized advertiser identity (advertiser_key(advertiser)); groups case/accent/spacing variants of one advertiser.';

-- Latest connector flag on the ad itself (written by the ingestion with each sync: ended = not
-- ad_observations.active of that day), so the active-ad rule and the Ad Spy filters need no join.
alter table public.advertisements
  add column if not exists ended boolean not null default false;

comment on column public.advertisements.ended is
  'The latest sync reported the ad as no longer running (ad_observations.active = false); last_seen is then its last delivery day.';

-- Existing rows: ended when an observation after the last delivery day reported the ad inactive.
update public.advertisements a
   set ended = true
 where not a.ended
   and exists (select 1 from public.ad_observations o where o.ad_id = a.id and not o.active and o.date > a.last_seen);

create index if not exists advertisements_advertiser_key_idx on public.advertisements (advertiser_key);
-- Activity on a day = a range scan on last_seen; covering first_seen, the key and ended allows index-only scans.
create index if not exists advertisements_activity_idx on public.advertisements (last_seen, advertiser_key, first_seen) include (ended);

-- Per-advertiser activity on as_of: active ads, active ads running for at least min_days, oldest active
-- first_seen. Only advertisers with at least one active ad are returned; `keys` (optional) restricts the
-- result to some advertiser keys (the advertisers of one result page).
create or replace function public.advertiser_activity(as_of date, min_days integer default 7, keys text[] default null)
returns table (advertiser_key text, active_ads integer, active_since_min_days integer, oldest_active_first_seen date)
language sql
stable
parallel safe
set search_path = pg_catalog
as $$
  select a.advertiser_key,
         count(*)::integer,
         (count(*) filter (where a.first_seen <= as_of - min_days))::integer,
         min(a.first_seen)
  from public.advertisements a
  where a.last_seen >= as_of - 1
    and (a.last_seen >= as_of or not a.ended)
    and a.first_seen <= as_of
    and (keys is null or a.advertiser_key = any (keys))
  group by a.advertiser_key
$$;

comment on function public.advertiser_activity(date, integer, text[]) is
  'Active-advertiser statistics on as_of (active = first_seen <= as_of and last_seen >= as_of, or >= as_of - 1 when not ended). Mirrors advertiserActivity() in src/lib/advertisers.ts.';

-- Ads of the advertisers that qualify on as_of. Used as the base relation of Ad Spy (PostgREST applies
-- the usual filters, order, range and exact count to it, so totals describe the filtered set).
-- No SET clause and fully qualified names: the planner can inline this SQL function into the calling
-- query, so filters, ORDER BY and LIMIT use the advertisements indexes.
create or replace function public.ads_of_active_advertisers(as_of date, min_ads integer default 5, min_days integer default 7)
returns setof public.advertisements
language sql
stable
as $$
  select a.*
  from public.advertisements a
  where a.advertiser_key in (
    select s.advertiser_key
    from public.advertiser_activity(as_of, min_days) s
    where s.active_since_min_days >= min_ads
  )
$$;

comment on function public.ads_of_active_advertisers(date, integer, integer) is
  'Every ad of the advertisers with >= min_ads active ads first seen >= min_days days before as_of (defaults 5 and 7).';

grant execute on function public.advertiser_key(text) to public;

-- Server only (Supabase grants new functions to anon/authenticated by default).
revoke all on function public.advertiser_activity(date, integer, text[]) from public, anon, authenticated;
revoke all on function public.ads_of_active_advertisers(date, integer, integer) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.advertiser_activity(date, integer, text[]) to service_role;
    grant execute on function public.ads_of_active_advertisers(date, integer, integer) to service_role;
  end if;
end;
$$;
